def get_available_boards():
    """Return list of distinct board keys."""
    return ["CBSE", "ICSE / ISC", "State / Other Board"]


def get_classes_for_board(board="CBSE"):
    """Return sorted list of supported classes (1-12) for a board."""
    b_data = CURRICULUM.get(board) or CURRICULUM.get("CBSE", {})
    return sorted(list(b_data.keys()), key=lambda x: int(x) if x.isdigit() else 99)


def get_subjects_for_class(cls="10", board="CBSE"):
    """Return available subjects for a specific class and board."""
    b_data = CURRICULUM.get(board) or CURRICULUM.get("CBSE", {})
    cls_data = b_data.get(str(cls), {})
    return list(cls_data.keys())


def get_chapters_and_topics(cls="10", subj="Science", board="CBSE"):
    """Return chapters and their topic breakdowns for class, subject and board."""
    b_data = CURRICULUM.get(board) or CURRICULUM.get("CBSE", {})
    cls_data = b_data.get(str(cls), {})
    
    # 1. Exact match
    if subj in cls_data:
        return cls_data[subj]
        
    # 2. Case-insensitive or partial match
    s_lower = subj.strip().lower()
    for s, chapters in cls_data.items():
        if s.lower() == s_lower or s_lower in s.lower() or s.lower() in s_lower:
            return chapters
            
    # 3. Fallback to CBSE if board was different
    if board != "CBSE":
        cbse_data = CURRICULUM.get("CBSE", {}).get(str(cls), {})
        if subj in cbse_data:
            return cbse_data[subj]
        for s, chapters in cbse_data.items():
            if s.lower() == s_lower or s_lower in s.lower() or s.lower() in s_lower:
                return chapters

    return []


def search_curriculum(query=""):
    """Search for chapters or topics matching a search string across all curriculum entries."""
    if not query:
        return []
    query = query.lower().strip()
    results = []
    seen = set()
    for board, b_data in CURRICULUM.items():
        for cls, c_data in b_data.items():
            for subj, chapters in c_data.items():
                for ch in chapters:
                    ch_name = ch.get("chapter", "")
                    topics = ch.get("topics", [])
                    if query in ch_name.lower() or any(query in t.lower() for t in topics):
                        key = (cls, subj, ch_name)
                        if key not in seen:
                            seen.add(key)
                            results.append({
                                "board": board,
                                "class": cls,
                                "subject": subj,
                                "chapter": ch_name,
                                "topics": topics
                            })
    return results

